using Nexo.Core.Domain.Bricks;
using Nexo.Core.Domain.Execution;
namespace Nexo.Spikes.FirstFlight;
public sealed class LiveProposedLogScannerBrick : DomainBrick
{
    public override Task<BrickOutput> ExecuteAsync(
        BrickInput input,
        ImplementationType implementation,
        IExecutionContext context,
        CancellationToken cancellationToken = default)
    {
        var logText = input.Get<string>("logText") ?? string.Empty;
        var lines = logText.Split(new char[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
        var errorCount = 0;
        var firstErrorMessage = string.Empty;
        foreach (var line in lines)
        {
            if (line.Contains("ERROR"))
            {
                errorCount++;
                if (firstErrorMessage == string.Empty)
                {
                    firstErrorMessage = line.Substring(line.IndexOf("ERROR") + 5).TrimStart(':', ' ');
                }
            }
        }
        var output = new BrickOutput { Summary = $"Found {errorCount} ERROR line(s); first: {firstErrorMessage}" };
        output.Set("errorCount", errorCount);
        output.Set("firstErrorMessage", firstErrorMessage);
        return Task.FromResult(output);
    }
}
